return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=3; plural=(n%10==1 && n%100!=11 ? 0 : n%10>=2 && n%10<=4 && (n%100<12 || n%100>14) ? 1 : 2);','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'Idite na pretragu dodataka','Activate %s' => 'Aktivirajte %s','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s</strong> zahtijeva da se <strong>%2$s</strong> instalira i aktivira. <a href="%4$s">%3$s</a>','Enter your code here' => 'Unesite svoj kod ovdje','Add %s' => 'Dodajte %s','Remove' => 'Ukloni','Order number and receipt will be sent to this email address.' => 'Broj narudžbe i račun će biti poslani na ovu email adresu.','Apartment, unit, building, floor, etc.' => 'Stan, jedinica, zgrada, sprat itd.','Shipping phone' => 'Telefon za dostavu','Only used for shipping-related questions.' => 'Koristi se samo za pitanja vezana za otpremu.','Single step' => 'Jedan korak','Click to go to the order summary' => 'Kliknite da biste otišli na sažetak narudžbe','Cart total:' => 'Ukupno u korpi:','Proceed to %s' => 'Nastavite do %s','Proceed to contact' => 'Nastavite sa kontaktom','Proceed to shipping' => 'Nastavite sa isporukom','Proceed to billing' => 'Nastavite sa naplatom','Proceed to payment' => 'Nastavite sa plaćanjem','Shipping method' => 'Način dostave','Additional notes' => 'Dodatne napomene','Payment method' => 'Način plaćanja','Step %1$s of %2$s' => 'Korak %1$s od %2$s','Change: %s' => 'Promjena: %s','Not selected yet.' => 'Još nije odabrano.','Same as shipping address' => 'Isto kao i adresa za dostavu','Same as billing address' => 'Isto kao i adresa za naplatu','Order summary' => 'Sažetak naloga','Edit cart' => 'Uredi kolica','Did you mean %s?' => 'Jeste li mislili %s?','Change email address to: {suggestion-value}' => 'Promijenite email adresu u: {suggestion-value}','This is a required field.' => 'Ovo je obavezno polje.','This is not a valid email address.' => 'Ovo nije važeća adresa e-pošte.','This field does not match the related field value.' => 'Ovo polje ne odgovara vrijednosti povezanog polja.','The CPF number "{cpf_number}" is invalid.' => 'CPF broj &quot;{cpf_number}&quot; je nevažeći.','The CNPJ number "{cnpj_number}" is invalid.' => 'CNPJ broj &quot;{cnpj_number}&quot; je nevažeći.','(Required)' => '(obavezno)','Checkout Header - Desktop' => 'Zaglavlje naplate - Desktop','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'Prikažite widgete u zaglavlju naplate za velike ekrane. Prikazuje se samo ako se koristi zaglavlje naplate dodatka.','Checkout Header - Mobile' => 'Zaglavlje naplate - Mobilni','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'Prikažite widgete ispod zaglavlja naplate za mobilne uređaje. Prikazuje se samo ako se koristi zaglavlje naplate dodatka.','Checkout Sidebar' => 'Bočna traka za naplatu','Display widgets on the checkout sidebar after the order summary.' => 'Prikažite widgete na bočnoj traci za naplatu nakon sažetka narudžbe.','Checkout Order Summary' => 'Sažetak narudžbe na naplatu','Display widgets inside the order summary at the checkout page.' => 'Prikažite widgete unutar sažetka narudžbe na stranici za naplatu.','Checkout Below Place Order' => 'Plaćanje ispod narudžbe','Display widgets below the place order button at the checkout page.' => 'Prikažite widgete ispod dugmeta za naručivanje na stranici za naplatu.','Checkout Footer' => 'Checkout Footer','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'Prikažite widgete na podnožju naplate. Prikazuje se samo ako se koristi podnožje za naplatu dodatka.','Classic' => 'Classic','Boxed' => 'U kutiji','Split' => 'Split','Minimalist' => 'Minimalistički','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'Fluid Checkout i Delivery Date dodaci CodeRockz','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>Otkrili smo da koristite dodatke Datum isporuke i preuzimanja za WooCommerce (besplatno i PRO) od CodeRockz. Integracija sa ovim dodacima je premještena u Fluid Checkout PRO.</p>','Upgrade to PRO' => 'Nadogradite na PRO','Fluid Checkout database updated successfully' => 'Baza podataka Fluid Checkout je uspješno ažurirana','The database changes where applied successfully.' => 'Baza podataka se mijenja tamo gdje je uspješno primijenjena.','Dismiss' => 'Odbaci','Fluid Checkout database update' => 'Ažuriranje baze podataka Fluid Checkout','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'Potrebne su neke promjene u bazi podataka. Kao i kod svakog ažuriranja, preporučujemo da <strong>napravite potpunu sigurnosnu kopiju svoje web stranice prije nego što nastavite</strong> .','Update database' => 'Ažurirajte bazu podataka','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Fluid Checkout nije kompatibilan sa izgledom naplate Divi Builder-a','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>Fluid Checkout treba klasični WooCommerce obrazac za naplatu zasnovan na kratkom kodu da bi radio. Kada koristite Divi Builder za prilagođavanje izgleda i osjećaja stranice za naplatu, klasični kratki kodovi se zamjenjuju prilagođenim widgetima iz Divi Buildera za svaki dio stranice za naplatu. Ovi prilagođeni widgeti nisu kompatibilni sa Fluid Checkout.</p><p> Uredite svoju stranicu za naplatu zamjenjujući Divi Builder widget sa tekstualnim widgetom koji sadrži kratki kod <code>[woocommerce_checkout]</code> .</p>','Edit the checkout page' => 'Uredite stranicu za naplatu','Read the documentation.' => 'Pročitajte dokumentaciju.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'Germanizirana PRO višestepena naplata mora biti onemogućena kada se koristi Fluid Checkout','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'Kada koristite Fluid Checkout, funkcija u više koraka iz germaniziranog PRO dodatka postaje nepotrebna i može uzrokovati <strong>kritične greške prilikom obrade novih narudžbi</strong> . Molimo onemogućite germaniziranu PRO višestepenu opciju naplate u postavkama dodatka.','Go to Germanized settings' => 'Idite na germanizirane postavke','Thanks for choosing Fluid Checkout!' => 'Hvala što ste odabrali Fluid Checkout!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'Već neko vrijeme koristite dodatak. Kako vam se dopada do sada?<br> Molimo da nam date brzu ocjenu, cijenimo svaku povratnu informaciju i ohrabruje nas da nastavimo poboljšavati dodatak :)','Rate the plugin' => 'Ocijenite dodatak','I need help!' => 'Treba mi pomoć!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'Neke funkcije WooCommerce Checkout Manager-a od strane Quadlayers-a možda neće raditi kako se očekuje kada ga koristite s Fluid Checkout-om. Pročitajte <a href="%s">našu dokumentaciju</a> za više informacija i alternativna rješenja.','Read documentation' => 'Pročitajte dokumentaciju','Don\'t show this again' => 'Ne pokazuj ovo ponovo','Fluid Checkout PRO' => 'Fluid Checkout PRO','More design templates' => 'Više šablona za dizajn','Optimized cart page' => 'Optimizirana stranica korpe','Optimized order received / thank you page' => 'Primljena optimizirana narudžba / stranica zahvale','Edit cart contents at checkout page' => 'Uredite sadržaj korpe na stranici za naplatu','Account matching / user matching' => 'Usklađivanje računa / podudaranje korisnika','Trust symbols on the cart and thank you pages' => 'Simboli povjerenja na stranicama kolica i zahvalnica','More positions for the coupon code on the checkout page' => 'Više pozicija za kupon kod na stranici za naplatu','International phone numbers' => 'Međunarodni brojevi telefona','Gift messages and packing slips' => 'Poklon poruke i pakovanje','Local pickup and in-store collection' => 'Lokalno preuzimanje i preuzimanje u trgovini','EU-VAT Assistant' => 'EU-PDV pomoćnik','I already have it – Hide this offer' => 'Već ga imam – Sakrij ovu ponudu','Activated' => 'Aktivirano','Address book' => 'Adresar','Select an image' => 'Odaberite sliku','Cart layout' => 'Izgled kolica','Cart optimizations' => 'Optimizacije kolica','Enable cart page optimizations' => 'Omogućite optimizaciju stranice korpe','Header and footer template' => 'Šablon zaglavlja i podnožja','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'Kontrolira da li koristiti zaglavlje i podnožje stranice bez ometanja ili zadržati zaglavlje i podnožje trenutno aktivne teme.','Distraction free header and footer' => 'Zaglavlje i podnožje bez ometanja','Theme\'s header and footer' => 'Zaglavlje i podnožje teme','Cart elements' => 'Elementi kolica','Make the order summary stay visible on the cart page while scrolling' => 'Neka sažetak narudžbe ostane vidljiv na stranici korpe dok se krećete','Coupon codes' => 'Kodovi kupona','Hidden' => 'Skriveno','Before the cart items section' => 'Prije odjeljka artikala u košarici','Inside the cart items section' => 'Unutar odjeljka artikala u košarici','After the cart items section' => 'Nakon odjeljka artikala u košarici','Before the shipping section' => 'Prije odjeljka za otpremu','After the shipping section' => 'Nakon odjeljka za otpremu','Before the order summary' => 'Prije sažetka narudžbe','Inside the order summary' => 'Unutar sažetka narudžbe','Before the order totals' => 'Prije zbroja narudžbe','After the order totals' => 'Nakon zbroja naloga','After the order summary' => 'Nakon sažetka narudžbe','Shipping' => 'Dostava','Select position where to display the shipping costs and calculator on the cart page.' => 'Odaberite poziciju na kojoj će se prikazati troškovi dostave i kalkulator na stranici korpe.','Display as a cart section' => 'Prikaži kao odeljak kolica','Cross-sells' => 'Unakrsne prodaje','Select position where to display the cross-sells section on the cart page.' => 'Odaberite poziciju na kojoj će se prikazati odjeljak unakrsnih prodaja na stranici korpe.','Before the cart actions' => 'Prije akcije kolica','After the cart actions' => 'Nakon akcije kolica','Layout of cross-sell items on the cart page.' => 'Izgled artikala unakrsne prodaje na stranici korpe.','Optimized horizontal cross-sells layout' => 'Optimiziran horizontalni raspored unakrsnih prodaja','Theme\'s cross-sells layout' => 'Izgled unakrsne prodaje teme','Number of cross-sell items to display on the cart page' => 'Broj artikala unakrsne prodaje za prikaz na stranici korpe','Add widget areas to the cart page' => 'Dodajte oblasti vidžeta na stranicu korpe','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'Ove oblasti vidžeta se koriste za dodavanje simbola poverenja i značaka poverenja na stranicu korpe.','Checkout' => 'Naplata','Checkout layout' => 'Izgled naplate','Design template' => 'Predložak dizajna','Dark mode' => 'Tamni mod','Enable dark mode' => 'Omogući tamni način rada','Logo image' => 'Logo slika','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'Odaberite sliku koja će se prikazati u zaglavlju stranice za naplatu. Primjenjuje se samo kada koristite zaglavlje i podnožje bez ometanja.','Header background color' => 'Boja pozadine zaglavlja','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'Odaberite boju pozadine za zaglavlje stranice naplate. Primjenjuje se samo kada koristite zaglavlje i podnožje bez ometanja.','HTML color value. ie: #f3f3f3' => 'HTML vrijednost boje. npr.: #f3f3f3','Page background color' => 'Boja pozadine stranice','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'Odaberite boju pozadine za stranicu za naplatu. Boja se primjenjuje na element <em>tijela</em> .','Footer background color' => 'Boja pozadine podnožja','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'Odaberite boju pozadine za podnožje stranice naplate. Primjenjuje se samo kada koristite zaglavlje i podnožje bez ometanja.','Progress bar' => 'Traka napretka','Display the checkout progress bar when using multi-step checkout layout' => 'Prikažite traku napretka naplate kada koristite izgled naplate u više koraka','Make the checkout progress bar stay visible while scrolling' => 'Neka traka toka naplate ostane vidljiva dok se krećete','Express checkout' => 'Ekspresno odjavljivanje','Enable the express checkout section' => 'Omogućite odjeljak za ekspresno plaćanje','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'Prikazuje odjeljak ekspresne naplate pri naplati kada podržani pristupnici plaćanja imaju omogućenu ovu funkciju.','Display express checkout buttons in one line for larger screens' => 'Prikažite dugmad za brzu naplatu u jednom redu za veće ekrane','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'Zanemarite dodatna polja obavezna za naplatu kada plaćate putem kompatibilnog prolaza za ekspresno plaćanje','Make the order summary stay visible while scrolling' => 'Neka sažetak narudžbe ostane vidljiv dok se krećete','Choose a background color for the order summary section.' => 'Odaberite boju pozadine za odjeljak sažetka narudžbe.','Highlight the order totals row in the order summary table' => 'Označite red ukupnih narudžbi u tabeli sažetka naloga','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'Najkorisnije kada odjeljak sažetka narudžbe nema istaknutu boju pozadine. Može se primijeniti i na stranice Košarica, Primljena narudžba i Pregled narudžbe kada koristite Fluid Checkout PRO.','Action link on the order summary at checkout.' => 'Link za akciju na sažetku narudžbe na blagajni.','Edit cart link' => 'Uredi link za korpe','Cart items count' => 'Broj artikala u korpi','Link to shop page' => 'Link do stranice prodavnice','Cart items' => 'Artikli u košarici','Hide cart items errors at the checkout page' => 'Sakrij greške stavki u korpi na stranici za naplatu','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'Ne prikazujte poruku o greškama u stavkama u korpi na vrhu stranice za naplatu. Prilikom slanja obrasca za naplatu da biste dovršili kupovinu, ove poruke o grešci će uvijek biti prikazane.','Place order' => 'Naručite','Define the position to display "Place order" and terms checkbox section.' => 'Definirajte poziciju za prikaz &quot;Postavite narudžbu&quot; i odjeljak za potvrdu termina.','Some options might not be compatible with some plugins and themes.' => 'Neke opcije možda neće biti kompatibilne s nekim dodacima i temama.','Below the payment section' => 'Ispod odjeljka plaćanja','Below the order summary' => 'Ispod sažetka narudžbe','Both below the payment section and the order summary' => 'I ispod odjeljka plaćanja i sažetka narudžbe','Add widget areas to the checkout page' => 'Dodajte oblasti vidžeta na stranicu za naplatu','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'Ove oblasti widgeta koriste se za dodavanje simbola povjerenja i znački povjerenja na stranici za naplatu.','Display the coupon codes section title' => 'Prikažite naslov odjeljka kodova kupona','Select position where to display the coupon codes section on the checkout page.' => 'Odaberite poziciju na kojoj će se prikazati odjeljak kodova kupona na stranici za naplatu.','Before the checkout steps' => 'Prije koraka naplate','As a substep before payment methods' => 'Kao podkorak prije načina plaćanja','As a substep after payment methods' => 'Kao podkorak nakon načina plaćanja','Default button style' => 'Zadani stil dugmeta','"Add" link button' => 'Dugme za vezu &quot;Dodaj&quot;.','Checkout fields' => 'Polja za naplatu','Optional fields' => 'Opciona polja','Hide optional fields behind a link button' => 'Sakrijte opciona polja iza dugmeta veze','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'Preporučuje se da ovu opciju držite označenu kako biste smanjili broj otvorenih polja za unos, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">pročitajte istraživanje</a> .','Do not hide "Address line 2" fields behind a link button' => 'Ne sakrivajte polja &quot;Adresni red 2&quot; iza dugmeta veze','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'Preporuča se samo kada većini kupaca zaista treba polje &quot;Address line 2&quot; ili kada je pronalaženje prave adrese za dostavu ključno (tj. ako dostavljate hranu i druge kvarljive proizvode).','Billing address' => 'Adresa za naplatu','Select position where to display the billing address section on the checkout page.' => 'Odaberite poziciju na kojoj će se prikazati odjeljak adrese za naplatu na stranici za naplatu.','As a step before shipping' => 'Kao korak prije isporuke','As a sub-step before the shipping address section' => 'Kao podkorak prije odjeljka adrese za dostavu','As a sub-step after the shipping address section' => 'Kao podkorak nakon odjeljka adrese za dostavu','As a step after shipping' => 'Kao korak nakon isporuke','As a sub-step before the payment section' => 'Kao podkorak prije odjeljka plaćanja','Force billing and shipping addresses to the same (single section)' => 'Prisilno postavljanje adrese za naplatu i dostavu na istu (jedan odjeljak)','Checkbox for "Same as shipping/billing address" checked by default' => 'Polje za potvrdu za &quot;Isto kao adresa za isporuku/fakturisanje&quot; označeno je prema zadanim postavkama','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'Polje za potvrdu &quot;Isto kao adresa za dostavu&quot; će početi kao što je označeno prema zadanim postavkama kada se prvi prikaže odjeljak adrese za dostavu.<br> Polje za potvrdu &quot;Isto kao adresa za naplatu&quot; će početi kao što je označeno prema zadanim postavkama kada se prvo prikaže odjeljak adrese za naplatu.<br> Preporučuje se da ovu opciju ostavite označenu kako biste značajno smanjili broj otvorenih polja za unos pri naplati, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">pročitajte istraživanje</a> .','Highlight the billing address section in the checkout form' => 'Označite odjeljak adrese za naplatu u obrascu za naplatu','Shipping address' => 'Adresa za dostavu','Highlight the shipping address section in the checkout form' => 'Označite odjeljak adrese za dostavu u obrascu za naplatu','Shipping methods' => 'Načini dostave','Choose in which position to display the shipping methods section.' => 'Odaberite u kojoj poziciji će se prikazati odjeljak o načinima dostave.','Before shipping address' => 'Prije slanja adresa','After shipping address' => 'Adresa nakon dostave','Local pickup' => 'Lokalno preuzimanje','Removes shipping address section when a local pickup shipping method is selected.' => 'Uklanja odjeljak s adresom dostave kada je odabran način dostave lokalnog preuzimanja.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'Zamjenjuje adresu dostave s lokacijom mjesta preuzimanja kada je odabran lokalni način dostave.','Choose which address to save as the shipping address for local pickup orders.' => 'Odaberite adresu koju želite sačuvati kao adresu za dostavu za lokalne narudžbe za preuzimanje.','Save the selected pickup location' => 'Sačuvajte odabranu lokaciju preuzimanja','Save same as the billing address' => 'Sačuvajte isto kao adresu za naplatu','Do not save any shipping address' => 'Nemojte spremati adresu za dostavu','Company name field for shipping address' => 'Polje za naziv kompanije za adresu dostave','Change visibility for the company name field for the shipping address section on the checkout form.' => 'Promijenite vidljivost polja naziva kompanije za odjeljak adrese dostave na obrascu za naplatu.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'Ako je polje postavljeno kao &quot;opciono&quot;, što je zadano stanje vidljivosti, neće biti primijenjene nikakve promjene kako bi drugi dodaci mogli primijeniti sve promjene koje su im potrebne.','Hidden (remove field)' => 'Skriveno (ukloni polje)','Optional' => 'Opciono','Required' => 'Obavezno','Add shipping phone field to the checkout form.' => 'Dodajte polje za telefon za isporuku u obrazac za naplatu.','Choose in which step to display the shipping phone field.' => 'Odaberite u kojem koraku će se prikazati polje za telefon za isporuku.','Contact step' => 'Kontakt korak','Billing phone' => 'Telefon za naplatu','Add billing phone field to the checkout form.' => 'Dodajte polje za telefon za naplatu u obrazac za naplatu.','Choose in which step to display the billing phone field.' => 'Odaberite u kojem koraku će se prikazati polje za telefon za naplatu.','Show country code beside the flag' => 'Prikaži pozivni broj zemlje pored zastave','Show an example of a valid phone number inside phone fields' => 'Pokažite primjer važećeg telefonskog broja unutar polja za telefon','Do not change placeholders' => 'Nemojte mijenjati čuvare mjesta','Show if not defined' => 'Prikaži ako nije definirano','Always show' => 'Uvijek pokazuj','Order notes' => 'Narudžbenice','Define the visibility of the additional order notes field.' => 'Definirajte vidljivost polja dodatnih napomena o narudžbi.','Gift options' => 'Opcije poklona','Allow customers to add a gift message and other gift related options to the order.' => 'Omogućite kupcima da dodaju poklon poruku i druge opcije vezane za poklon narudžbi.','Display the gift message as part of the order details table instead of a separate section' => 'Prikažite poruku o poklonu kao dio tabele s detaljima narudžbe umjesto kao poseban odjeljak','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'Ova opcija utječe na stranicu za potvrdu narudžbe (stranica zahvalnosti) i detalje narudžbe na stranicama računa, e-porukama i otpremnicama.','Account matching' => 'Usklađivanje računa','Enable the account matching feature' => 'Omogućite funkciju podudaranja računa','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'Povežite narudžbe gosta s njihovim postojećim računom kada račun već postoji s kontakt podacima kupca.','Display message when an account exists with the email address provided' => 'Prikažite poruku kada postoji nalog sa navedenom adresom e-pošte','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'Zamjenjuje polja za kreiranje naloga obavještenjem i opcijom za prijavu. U nekim kontekstima, može se preporučiti da ovu opciju ostavite onemogućenu radi zaštite privatnosti kupaca.','Dashboard' => 'Dashboard','Integrations' => 'Integracije','License keys' => 'Licencni ključevi','Visit our website for more information about our plugins and add-ons.' => 'Posjetite našu web stranicu za više informacija o našim dodacima i dodacima.','Order pay page' => 'Stranica za plaćanje','Order pay' => 'Naručite plaćanje','Enable order pay page optimizations' => 'Omogućite optimizaciju stranice za plaćanje naloga','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'Mijenja izgled stranice za plaćanje narudžbe za postojeće narudžbe koje čekaju plaćanje od kupca.','Add widget areas to the order pay page' => 'Dodajte widget područja na stranicu za plaćanje narudžbe','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'Ove oblasti widgeta koriste se za dodavanje simbola povjerenja i značaka povjerenja na stranici plaćanja narudžbe.','Thank you page & order details layout' => 'Stranica zahvale i raspored detalja narudžbe','Order details optimizations' => 'Optimizacija detalja narudžbe','Enable thank you page and order details optimizations' => 'Omogućite optimizaciju stranice zahvale i detalja narudžbe','Changes the layout of order details on the thank you page and account pages.' => 'Mijenja izgled detalja narudžbe na stranici zahvale i stranicama računa.','Enable order details customizations on email notifications' => 'Omogućite prilagođavanje detalja narudžbe u obavještenjima putem e-pošte','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'Prikažite nove odjeljke i promijenite redoslijed odjeljaka na obavještenjima putem e-pošte. Stilovi detalja narudžbi u obavještenjima putem e-pošte ostaju nepromijenjeni.','Thank you page' => 'Hvala stranica','These options affect the thank you page, also known as order received or order confirmation pages.' => 'Ove opcije utječu na stranicu zahvale, također poznatu kao primljene narudžbe ili stranice za potvrdu narudžbe.','Order details layout' => 'Izgled detalja narudžbe','Display the order details with wide layout on the thank you page' => 'Prikažite detalje narudžbe sa širokim izgledom na stranici zahvale','Add widget areas to the thank you page' => 'Dodajte widget područja na stranicu zahvale','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'Ove oblasti widgeta koriste se za dodavanje simbola povjerenja i značaka povjerenja na stranicu zahvale.','Order actions' => 'Naručite akcije','Choose in which position to display the order actions.' => 'Odaberite u kojoj poziciji će se prikazati radnje naloga.','Inside the order overview' => 'Unutar pregleda narudžbi','After the order overview' => 'Nakon pregleda narudžbe','After order sections' => 'Nakon porudžbine sekcije','Order status' => 'Status narudžbe','Display the order status progress bar' => 'Prikažite traku napretka statusa narudžbe','Choose in which position to display the section.' => 'Odaberite u kojoj poziciji želite prikazati odjeljak.','After the order overview and payment instructions' => 'Nakon narudžbe pregled i upute za plaćanje','Before the order items section' => 'Prije odjeljka artikala narudžbe','Inside the order items section' => 'Unutar odjeljka stavki narudžbe','After the order items section' => 'Nakon odjeljka artikala narudžbe','On the sidebar' => 'Na bočnoj traci','Order downloads' => 'Naručite preuzimanja','Gift message' => 'Poklon poruka','Tools' => 'Alati','Troubleshooting' => 'Rješavanje problema','Debug options' => 'Opcije za otklanjanje grešaka','Debug mode' => 'Režim za otklanjanje grešaka','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'Korištenje načina za otklanjanje grešaka utječe na performanse web stranice. Ovu opciju koristite samo tokom rješavanja problema.','Load unminified assets' => 'Učitajte neminificirana sredstva','Enhanced select fields' => 'Poboljšana polja za odabir','Fix automatic zoom-in on form fields' => 'Popravite automatsko zumiranje polja obrasca','Set <code>font-size</code> inside form fields to 16px' => 'Postavite <code>font-size</code> unutar polja obrasca na 16px','Fluid Checkout' => 'Fluid Checkout','Settings' => 'Postavke','Support' => 'Podrška','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => '<a target="_blank" href="%s">Nadogradite na PRO</a> da otključate više opcija.','(PRO)' => '(PRO)','(experimental)' => '(eksperimentalno)','Please verify your phone number.' => 'Molimo potvrdite svoj broj telefona.','The Bluehost Plugin' => 'Bluehost dodatak','Custom fields' => 'Prilagođena polja','Enable custom shipping email field' => 'Omogućite prilagođeno polje e-pošte za isporuku','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'Kada je omogućeno, polje e-pošte za isporuku iz Bluehost dodatka bit će dodano u obrazac za naplatu.','Captcha Pro by BestWebSoft' => 'Captcha Pro od BestWebSoft','Captcha position' => 'Captcha pozicija','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'Definirajte poziciju za prikaz captcha odjeljka. Neke pozicije možda neće raditi ovisno o odabranoj vrsti captcha.','Selecting a pickup point is required before proceeding.' => 'Prije nastavka potrebno je odabrati mjesto preuzimanja.','Pickup point' => 'Mjesto preuzimanja','Pickup point not selected yet.' => 'Mjesto preuzimanja još nije odabrano.','Pickup point:' => 'mjesto preuzimanja:','Mailchimp for WooCommerce' => 'Mailchimp za WooCommerce','Subscribe checkbox' => 'Potvrdni okvir za pretplatu','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'Poništite poziciju za potvrdni okvir za pretplatu na stranici za naplatu i uvijek ga prikažite na koraku za kontakt','Before Shipping Address' => 'Prije slanja adresa','(originally "%s")' => '(prvobitno &quot;%s&quot;)','After Shipping Address' => 'Adresa nakon dostave','Selecting a collection point is required when shipping with FermoPoint.' => 'Odabir mjesta prikupljanja je obavezan kada se isporučuje s FermoPointom.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'Ako je označeno, obavještava korisnike o greškama u e-poruci. (Ova funkcija je onemogućena jer Fluid Checkout nudi ovu funkciju. Promjene ove opcije neće stupiti na snagu)','Enable Mail Check: (disabled feature)' => 'Omogući provjeru pošte: (onemogućena funkcija)','Carrier:' => 'prijevoznik:','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - WooCommerce e-mail marketing','Sign up checkbox position' => 'Prijava u polje za potvrdu','Move the sign up checkbox to the contact step' => 'Pomaknite polje za potvrdu prijave na korak za kontakt','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'Kada je omogućeno, potvrdni okvir će se premjestiti na korak kontakta neovisno o lokaciji prikaza definiranoj u postavkama dodatka Sendinblue.','Theme Betheme' => 'Tema Betheme','Checkout progress' => 'Napredak naplate','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'Ispišite odjeljak koraka naplate iz Bethemea na stranicama za naplatu, košaricu i narudžbu.','Theme Fennik' => 'Tema Fennik','Breadcrumbs' => 'Breadcrumbs','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'Iznesite odjeljak krušnih mrvica iz Fennik teme kada koristite zaglavlje i podnožje Fluid Checkout.','Theme Go' => 'Theme Go','My account layout' => 'Izgled mog naloga','Enable wide layout on "My account" page.' => 'Omogućite široki izgled na stranici &quot;Moj nalog&quot;.','Theme Impreza' => 'Theme Impreza','Header' => 'Zaglavlje','Spacing for site header at the checkout page (in pixels)' => 'Razmak za zaglavlje stranice na stranici za naplatu (u pikselima)','Only applicable when using the Impreza theme header at the checkout page.' => 'Primjenjivo samo kada koristite zaglavlje teme Impreza na stranici za naplatu.','Theme Kapee' => 'Tema Kapee','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'Ispišite odjeljak o koracima naplate iz teme Kapee na stranicama za naplatu, košaricu i narudžbu.','Theme Porto' => 'Tema Porto','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'Ispišite odjeljak koraka naplate iz Porto teme na stranicama za naplatu, košaricu i narudžbu.','Theme Pressmart' => 'Theme Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'Ispišite odjeljak o koracima naplate iz teme Pressmart na stranicama za naplatu, košaricu i narudžbu.','Theme The Gem' => 'Theme The Gem','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'Iznesite odjeljak o koracima naplate iz teme Gem kada koristite zaglavlje i podnožje Fluid Checkout.','Theme Woodmart' => 'Tema Woodmart','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'Iznesite dio koraka naplate iz Woodmart teme kada koristite zaglavlje i podnožje Fluid Checkout.','Checkout options' => 'Opcije plaćanja','Disable the theme checkout options' => 'Onemogućite opcije plaćanja teme','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'Opcije prikaza slike proizvoda, polja za količinu, dugmeta za uklanjanje i veze do stranice proizvoda koju je dodala tema su podrazumevano onemogućene.','Theme Atomion' => 'Theme Atomion','Order progress' => 'Napredak narudžbe','Display order progress from the theme' => 'Prikaži napredak narudžbe iz teme','Display the form field labels visible on the page' => 'Prikažite oznake polja obrasca vidljive na stranici','It is recommended to keep this option enabled for a better user experience.' => 'Preporučuje se da ova opcija ostane uključena radi boljeg korisničkog iskustva.','Theme ZK Nito' => 'Tema ZK Nito','Add extra fields to the checkout form' => 'Dodajte dodatna polja u obrazac za naplatu','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'Dodaje dodatnu adresu e-pošte za isporuku i polje za telefon za dostavu u odjeljak adrese za dostavu.','Go to the home page' => 'Idite na početnu stranicu','Skip to content' => 'Preskoči na sadržaj','Create an account' => 'Kreirajte nalog','Log in to your account' => 'Prijavite se na svoj račun','Already have an account?' => 'Već imate račun?','Logged in as %1$s. <a href="%2$s">Log out</a>' => 'Prijavljen kao %1$s. <a href="%2$s">Odjavite se</a>','Your order has a total amount due of %s. No further payment is needed.' => 'Ukupan iznos vaše narudžbe iznosi %s. Nije potrebno dalje plaćanje.','Close and continue with checkout' => 'Zatvorite i nastavite s naplatom','Continue' => 'Nastavi','Parcel terminal' => 'Parcelni terminal','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>Ovaj widget je zamijenjen Fluid Checkout.</p><p> Kada koristite Fluid Checkout, stranica za naplatu mora koristiti originalni WooCommerce kratki kod <code>[woocommerce_checkout]</code> da bi ispravno radila.</p><p> Za više informacija posjetite dokumentaciju Fluid Checkout.</p>','Theme The7' => 'Theme The7','Additional header sections' => 'Dodatni odjeljci zaglavlja','Output additional header sections if enabled in the theme settings.' => 'Iznesite dodatne sekcije zaglavlja ako je omogućeno u postavkama teme.','More information' => 'Više informacija','Pick a Locker' => 'Odaberite ormarić','Page template' => 'Predložak stranice','Use `Order confirmation` page template for block-based themes' => 'Koristite predložak stranice `Potvrda narudžbe` za teme zasnovane na blokovima','Only applies when using a block-based theme.' => 'Primjenjuje se samo kada se koristi tema zasnovana na blokovima.','WooCommerce Stripe Gateway' => 'WooCommerce Stripe Gateway','Payment form' => 'Obrazac za plaćanje','Apply styles to the Stripe payment form fields' => 'Primjena stilova na polja Stripe obrasca za plaćanje','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'Kada je omogućeno, Fluid Checkout će primijeniti stilove optimizirane za kompatibilnost s dodatkom. Možda biste željeli onemogućiti ovo ako koristite prilagođene stilove za polja Stripe obrasca za plaćanje.','Theme Nyture' => 'Tema Nyture','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'Ispišite odjeljak s koracima naplate iz Nyture teme kada koristite Fluid Checkout.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'Omogućava kupcima plaćanje za narudžbe koje je ručno kreirao administrator trgovine ili koje nisu dovršene tokom plaćanja.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'Dodatak WooCommerce Checkout Manager od Quadlayersa nije kompatibilan sa Fluid Checkout-om.','Company name field for billing address' => 'Polje za naziv kompanije za adresu za naplatu','Change visibility for the company name field for the billing address section on the checkout form.' => 'Promijenite vidljivost polja za naziv kompanije za odjeljak adrese za naplatu na obrascu za plaćanje.','Theme Bookshelf' => 'Tematska polica za knjige','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'Ispišite odjeljak s koracima naplate iz teme Bookshelf kada koristite Fluid Checkout.','Account password' => 'Lozinka računa','An account will be created with the information provided at checkout when completing the order.' => 'Prilikom narudžbe, bit će kreiran račun s podacima koje ste unijeli prilikom plaćanja.','Choose the style of the progress bar.' => 'Odaberite stil trake napretka.','Bars' => 'Barovi','Theme Ireca' => 'Tema Ireca','WooCommerce page layout' => 'Izgled WooCommerce stranice','Force wide layout on WooCommerce pages' => 'Nametnite široki raspored na WooCommerce stranicama','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'Ovo osigurava da odjeljak sa sadržajem nije preuzak na WooCommerce stranicama, uključujući stranice za naplatu, korpu, primljenu narudžbu, plaćanje narudžbe i račun.','WooCommerce Smart Coupons' => 'WooCommerce pametni kuponi','Position on checkout page' => 'Pozicija na stranici za plaćanje','Choose where to display the available coupons section on the checkout page.' => 'Odaberite gdje će se na stranici za plaćanje prikazivati odjeljak dostupnih kupona.','Before the progress bar' => 'Prije trake napretka','After the progress bar' => 'Nakon trake napretka','Before coupon codes section' => 'Prije odjeljka s kodovima kupona','Format phone numbers according to the rules for each country.' => 'Formatirajte brojeve telefona prema pravilima za svaku zemlju.','Use precise phone number validation' => 'Koristite preciznu validaciju broja telefona','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'Ovo je eksperimentalna funkcija i možda neće raditi kako se očekuje u svim postavkama. Koristite je s oprezom.','Phone number validation types used when precise validation is enabled.' => 'Vrste validacije telefonskog broja koje se koriste kada je omogućena precizna validacija.','Mobile' => 'Mobilni','Fixed line' => 'Fiksna linija','Toll free' => 'Besplatni poziv','Contact' => 'Kontakt','Multi step' => 'Više koraka','2 columns' => '2 kolone','1 column' => '1 kolona','Before checkout steps' => 'Koraci prije plaćanja','Or' => 'Ili','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => 'Prilikom korištenja rasporeda naplate <em>&quot;1 kolona&quot;,</em> ova opcija je uvijek postavljena na <em>&quot;Prije koraka naplate&quot;</em> i primjenjuje se i na prikaz za računar.','Position for the extra order summary section on mobile.' => 'Pozicija za dodatni odjeljak sažetka narudžbe na mobilnom uređaju.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => 'Opcija <em>&quot;Na zaglavlju stranice&quot;</em> primjenjuje se samo kada se koristi zaglavlje bez ometanja.','On the site header (requires distraction-free header)' => 'U zaglavlju stranice (zahtijeva zaglavlje bez ometanja)','Initial state for the expansible order summary section on mobile.' => 'Početno stanje za proširivi odjeljak sažetka narudžbe na mobilnom uređaju.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'Preporučujemo da ga postavite kao <em>prošireno</em> za sljedeće zemlje zbog regulatornih zahtjeva: <strong>Njemačka</strong> , <strong>Austrija</strong> , <strong>Švicarska</strong> , <strong>Nizozemska</strong> , <strong>Poljska</strong> , <strong>Belgija</strong> i <strong>Francuska</strong> .','Collapsed' => 'Suženo','Expanded' => 'Prošireno','Do not show' => 'Ne prikazuj','yes' => 'da','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Polje za broj telefona za dostavu može biti &quot;obavezno&quot; ako se odjeljak za adresu za naplatu prikazuje nakon odjeljka za adresu za dostavu, a polje za broj telefona za naplatu je postavljeno kao &quot;obavezno&quot;. Ovo je potrebno kako bi se osiguralo da se adresa za dostavu može kopirati na adresu za naplatu kada je ta opcija označena, u suprotnom kupac možda neće moći popuniti obrazac za naplatu.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Polje za broj telefona za naplatu može biti &quot;obavezno&quot; ako se odjeljak za adresu za naplatu prikazuje prije odjeljka za adresu za dostavu, a polje za broj telefona za dostavu je postavljeno kao &quot;obavezno&quot;. Ovo je potrebno kako bi se osiguralo da se adresa za dostavu može kopirati na adresu za naplatu kada je ta opcija označena, u suprotnom kupac možda neće moći popuniti obrazac za naplatu.','Settings profiles' => 'Profili postavki','Settings profile' => 'Postavke profila','You do not have permission to perform this action.' => 'Nemate dozvolu za izvršavanje ove radnje.','You do not have permission to activate plugins.' => 'Nemate dozvolu za aktiviranje dodataka (plug-inova).','Missing plugin.' => 'Nedostaje dodatak.','Plugin activated.' => 'Dodatak je aktiviran.','The following changes will be applied:' => 'Sljedeće promjene će biti primijenjene:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'Od verzije Fluid Checkout 5.0, postavke se spremaju drugačije. Stare opcije se i dalje pohranjuju u bazi podataka kako bi se omogućio povratak na prethodne verzije ako je potrebno.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'Vaša trgovina već oko 2 sedmice radi s novim postavkama, tako da ste mogli očistiti naslijeđene opcije pohranjene u bazi podataka. Imajte na umu da će nakon čišćenja, ako trebate preći na prethodne verzije dodatka, koristiti zadane vrijednosti za sve postavke.','Fluid Checkout settings cleanup' => 'Čišćenje postavki Fluid Checkout-a','Delete leftover options' => 'Izbriši preostale opcije','Help us improve Fluid Checkout' => 'Pomozite nam da poboljšamo Fluid Checkout','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'Podijelite anonimne izvještaje o okruženju web-mjesta s Fluid Checkout-om kako biste dobili bržu podršku i pomogli nam da poboljšamo kompatibilnost i izmjerimo utjecaj. Nisu uključeni podaci o kupcima, korisnicima ili osjetljivi podaci. Možete odabrati šta se dijeli u bilo kojem trenutku iz postavki Alata.','Enable site environment reports' => 'Omogući izvještaje o okruženju lokacije','Review settings' => 'Pregled postavki','This preview has expired. Reload the admin page to start a new preview.' => 'Ovaj pregled je istekao. Ponovo učitajte administratorsku stranicu da biste započeli novi pregled.','Preview expired' => 'Pregled je istekao','Orders cannot be placed in the preview.' => 'Narudžbe se ne mogu izvršiti u pregledu.','Logging in is not available in the preview.' => 'Prijava nije dostupna u pregledu.','Accounts cannot be created in the preview.' => 'Računi se ne mogu kreirati u pregledu.','Requests to other sites are blocked in the preview.' => 'Zahtjevi prema drugim web-lokacijama su blokirani u pregledu.','Processing…' => 'Obrada…','Something went wrong. Please try again.' => 'Nešto nije u redu. Pokušajte ponovo.','Activate plugin' => 'Aktiviraj dodatak','Fluid Checkout PRO - The complete checkout package' => 'Fluid Checkout PRO - Kompletan paket za plaćanje','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'Sve PRO funkcije + svi dodaci, jedna cijena. Predlošci dizajna, optimizirane stranice za korpu i primljene narudžbe, usklađivanje računa i još mnogo toga.','Optimized order pay page' => 'Optimizirana stranica za plaćanje narudžbe','Express checkout buttons from supported payment methods' => 'Dugmad za ekspresno plaćanje iz podržanih načina plaćanja','Delayed account creation' => 'Odloženo kreiranje računa','Address autocomplete with Google Maps APIs' => 'Automatsko dovršavanje adrese pomoću Google Maps API-ja','Multiple saved addresses with the address book' => 'Više sačuvanih adresa u adresaru','EU-VAT assistant' => 'Asistent za PDV u EU','Hide this section' => 'Sakrij ovaj odjeljak','Learn more' => 'Saznajte više','Get early access' => 'Ostvarite rani pristup','Activate add-on' => 'Aktiviraj dodatak','Get more out of your checkout journey' => 'Izvucite maksimum iz procesa plaćanja','Test API key' => 'Testni API ključ','Guided setup' => 'Vođeno podešavanje','Options' => 'Opcije','Set up layout and design on the <a href="%s">checkout options</a>.' => 'Podesite izgled i dizajn <a href="%s">opcija na blagajni</a> .','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'Omogućite plaćanje gostu i/ili pregledajte <a href="%s">postavke korisničkih računa</a> .','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'Omogućite optimizirane stranice <a href="%1$s">za korpu</a> , <a href="%2$s">zahvalu</a> i <a href="%3$s">plaćanje narudžbe</a> .','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Omogući <a href="%s">automatsko dovršavanje adrese</a> iz Google mapa.','Enable multiple saved addresses with <a href="%s">address book</a>.' => 'Omogućite više sačuvanih adresa pomoću <a href="%s">adresara</a> .','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'Provjerite da li postoje dostupne <a href="%s">opcije integracije</a> za temu ili druge dodatke koje ste instalirali.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'Dobijte bržu podršku i pomozite nam da poboljšamo kompatibilnost i izmjerimo utjecaj. <a href="%s">Omogućite praćenje korištenja</a> u postavkama alata.','Missing settings tab.' => 'Nedostaje kartica postavki.','Getting started' => 'Početak','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>Odlično! Vaša stranica za plaćanje sada radi na Fluid Checkout-u.</strong> Evo nekoliko koraka za početak:','Completed' => 'Završeno','Preview report data' => 'Pregled podataka izvještaja','Send now' => 'Pošalji sada','Auto-detect' => 'Automatsko otkrivanje','Afrikaans' => 'Afrikanerski','Albanian' => 'Albanski','Amharic' => 'Amharski','Arabic' => 'arapski','Armenian' => 'Armenski','Azerbaijani' => 'Azerbejdžanski','Basque' => 'baskijski','Belarusian' => 'Bjeloruski','Bengali' => 'Bengalski','Bosnian' => 'Bosanski','Bulgarian' => 'bugarski','Burmese' => 'Burmanski','Catalan' => 'Katalonski','Chinese' => 'kineski','Chinese (Simplified)' => 'Kineski (pojednostavljeni)','Chinese (Hong Kong)' => 'Kineski (Hong Kong)','Chinese (Traditional)' => 'Kineski (tradicionalni)','Croatian' => 'hrvatski','Czech' => 'Češki','Danish' => 'Danski','Dutch' => 'holandski','English' => 'Engleski','English (Australian)' => 'Engleski (australijski)','English (Great Britain)' => 'Engleski (Velika Britanija)','Estonian' => 'Estonski','Farsi' => 'Farsi','Finnish' => 'Finski','Filipino' => 'Filipinski','French' => 'Francuski','French (Canadian)' => 'Francuski (kanadski)','Galician' => 'galicijski','Georgian' => 'Gruzijski','German' => 'njemački','Greek' => 'Grčki','Gujarati' => 'Gudžaratski','Hebrew' => 'Hebrejski','Hindi' => 'Hindski','Hungarian' => 'Mađarski','Icelandic' => 'Islandski','Indonesian' => 'Indonezijski','Italian' => 'Italijanski','Japanese' => 'Japanski','Kannada' => 'Kannada','Kazakh' => 'Kazaški','Khmer' => 'Kmerski','Korean' => 'Korejski','Kyrgyz' => 'Kirgizi','Lao' => 'Lao','Latvian' => 'Latvijski','Lithuanian' => 'Litvanski','Macedonian' => 'Makedonski','Malay' => 'Malajski','Malayalam' => 'Malajalamski','Marathi' => 'Marati','Mongolian' => 'Mongolski','Nepali' => 'Nepalski','Norwegian' => 'Norveški','Polish' => 'Poljski','Portuguese' => 'Portugalski','Portuguese (Brazil)' => 'Portugalski (Brazil)','Portuguese (Portugal)' => 'Portugalski (Portugal)','Punjabi' => 'Pandžapski','Romanian' => 'Rumunski','Russian' => 'Ruski','Serbian' => 'Srpski','Sinhalese' => 'Sinhalski','Slovak' => 'Slovački','Slovenian' => 'Slovenski','Spanish' => 'Španski','Spanish (Latin America)' => 'Španski (Latinska Amerika)','Swahili' => 'Svahili','Swedish' => 'švedski','Tamil' => 'Tamilski','Telugu' => 'Telugu','Thai' => 'Tajlandski','Turkish' => 'turski','Ukrainian' => 'Ukrajinski','Urdu' => 'Urdu','Vietnamese' => 'Vijetnamski','Zulu' => 'Zulu','Google address autocomplete' => 'Automatsko dovršavanje Google adrese','Google Places API version' => 'Verzija API-ja za Google mjesta','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Odaberite koju verziju Google Places API-ja želite koristiti. Preporučujemo da što prije pređete na novi Places API.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'Preporučujemo korištenje &quot;Places API (Novo)&quot; verzije, jer će od 1. marta 2025. godine Google premjestiti verziju &quot;Places API (Zastarjelo)&quot; u status Zastarjele verzije, što znači da više nećete moći omogućiti ovu uslugu za nove API ključeve i da ta verzija API-ja na kraju više neće biti dostupna. Postojeći računi koji već koriste Zastarjeli API mogu nastaviti raditi bez prekida.','(Recommended)' => '(Preporučeno)','Google API key' => 'Ključ Google API-ja','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'Zalijepite svoj Google API ključ i koristite dugme za testiranje kako biste potvrdili da radi za ovu web stranicu. Provjerite je li ključ važeći i dozvoljen za vašu domenu, u suprotnom bi se polje za adresu moglo blokirati, što bi spriječilo kupce da izvrše svoje narudžbe.','Enable Google address autocomplete' => 'Omogući automatsko dovršavanje Google adrese','Enable address autocompletion using the Google Maps APIs.' => 'Omogućite automatsko dovršavanje adrese pomoću Google Maps API-ja.','Google API language' => 'Jezik Google API-ja','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'Ovaj jezik će se koristiti za prikaz prijedloga adresa za Google Places API, a adrese će se također automatski dovršavati na ovom jeziku.','Result types' => 'Vrste rezultata','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Ostavite prazno da biste prihvatili bilo koju vrstu rezultata, što obično daje bolje rezultate podudaranja. <a href="%s" target="_blank">Pogledajte dokumentaciju za više detalja</a> .<br> Odaberite do 5 vrsta rezultata pretrage adresa koje će se vratiti u poljima za automatsko dovršavanje adresa.<br> Posjetite dokumentaciju Google mapa da biste saznali više o <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">podržanim tipovima</a> .','Result types (Legacy API)' => 'Vrste rezultata (Legacy API)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Koju vrstu rezultata pretrage adresa vratiti kada se koristi Places API (Legacy).<br> Posjetite dokumentaciju za Legacy Google Places API da biste saznali više o <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">podržanim tipovima</a> .','Company fields' => 'Polja kompanije','Enable autocomplete for the company name if available' => 'Omogućite automatsko dovršavanje za naziv kompanije ako je dostupno','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Omogućite automatsko dovršavanje polja kompanije s informacijama o nazivu kompanije kada se vrati iz Google Maps API-ja.','Business search' => 'Pretraga preduzeća','Enable search for businesses in the company field' => 'Omogući pretragu preduzeća u polju kompanije','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'Omogućite predlaganje adresa povezanih s firmom prilikom kucanja u polje za firmu, a zatim automatsko popunjavanje svih polja za adrese kada se firma odabere iz prijedloga.','Company result types' => 'Vrste rezultata kompanije','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Odaberite do 5 vrsta rezultata pretrage adresa koje će se vratiti prilikom automatskog popunjavanja polja kompanije.<br> Preporučena vrijednost je <code>establishment</code> , što uključuje većinu vrsta preduzeća.<br> Ostavite prazno da biste prihvatili bilo koju vrstu rezultata, uključujući rezultate koji nisu povezani s preduzećima.<br> Posjetite dokumentaciju Google mapa da biste saznali više o <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">podržanim tipovima</a> .','Google logo' => 'Googleov logotip','Show text and logo "Powered by Google"' => 'Prikaži tekst i logo &quot;Pokreće Google&quot;','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'Kada je označeno, tekst i logotip &quot;Powered by Google&quot; će se prikazivati na dnu okvira za prijedloge automatskog dovršavanja adrese.','Brasil API address autocomplete' => 'Automatsko dovršavanje adrese za Brazilski API','Brasil API' => 'Brazilski API','Enable Brasil API address autocomplete for CEP fields' => 'Omogući automatsko dovršavanje adrese Brasil API-ja za CEP polja','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'Koristite Brasil API za preuzimanje i automatsko popunjavanje adresa pomoću polja CEP/Poštanski broj. Relevantno samo za brazilske adrese.','API version' => 'Verzija API-ja','Choose which version of the Brasil API CEP method to use.' => 'Odaberite koju verziju Brasil API CEP metode želite koristiti.','Address book migration' => 'Migracija adresara','WooCommerce addresses' => 'WooCommerce adrese','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'Kopirajte postojeće adrese za dostavu i naplatu iz WooCommerce-a u adresar kupaca.','Enable the address book feature' => 'Omogućite funkciju adresara','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'Omogućite kupcima da sačuvaju više adresa i definišu podrazumevanu adresu koja će se koristiti za dostavu i naplatu.','Address labels' => 'Etikete adresa','Allow customers to add a custom label for each address' => 'Omogućite kupcima da dodaju prilagođenu oznaku za svaku adresu','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'Naljepnice s adresama olakšavaju kupcima razlikovanje između sačuvanih adresa (npr. &quot;Mamina kuća&quot;). Naljepnice s adresama su privatne za kupce i neće biti prikazane ili odštampane na stranici s detaljima narudžbe ili fakturama.','Display layout' => 'Raspored prikaza','Choose how saved addresses are displayed at checkout and on the cart.' => 'Odaberite kako će se sačuvane adrese prikazivati prilikom plaćanja i u korpi.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'Primjenjuje se prilikom plaćanja i u korpi. Sačuvane adrese na stranici računa uvijek koriste raspored kartica.','Address cards' => 'Kartice s adresom','Address list' => 'Adresar','Dropdown field' => 'Padajuće polje','Address search' => 'Pretraga adresa','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'Prikaži filter za pretragu adresa na frontendu kada korisnik ima na raspolaganju barem ovaj broj sačuvanih adresa.','Not used when display layout is set to dropdown field.' => 'Ne koristi se kada je raspored prikaza postavljen na padajuće polje.','Addresses' => 'Adrese','Enable cart page optimizations to see more options' => 'Omogućite optimizacije stranice korpe da biste vidjeli više opcija','Sticky order summary' => 'Sažetak ljepljive narudžbe','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Odaberite poziciju na kojoj će se prikazivati odjeljak s kuponima na stranici košarice. Primjenjivo samo kada je AJAX košarica omogućena i ako je korištenje kupona omogućeno u postavkama WooCommerce-a.','Layout of cross-sell' => 'Raspored unakrsne prodaje','Cross-sells displayed' => 'Prikazane unakrsne prodaje','Items' => 'Stavke','Cart page optimization' => 'Optimizacija stranice korpe','Give your cart the same clear, conversion-focused layout as your checkout.' => 'Dajte svojoj korpi isti jasan, na konverziju usmjeren izgled kao i vašoj blagajni.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'Uskladite izgled korpe sa stranicom za naplatu za dosljedan proces kupovine.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'Održavajte korpu ažuriranom u pozadini, bez ponovnog učitavanja cijele stranice kada se količine promijene.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'Postavite kupone, dostavu i unakrsnu prodaju tačno tamo gdje ostvaruju najbolju konverziju.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'Održavajte sažetak narudžbe vidljivim tokom skrolovanja i dodajte simbole povjerenja tamo gdje kupcima treba uvjeravanje.','Columns' => 'Kolone','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'Opći stilovi za korake naplate, sažetak narudžbe i ostale odjeljke. Odnosi se na ostale stranice za naplatu, korpu, zahvalu (narudžba primljena) i pregled narudžbe.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => 'Prilikom korištenja rasporeda <em>&quot;1 kolona&quot;</em> s predloškom dizajna <em>&quot;Podijeljeno&quot;</em> , desna kolona se prikazuje samo ako je aktivno područje widgeta bočne trake stranice (bočna traka za plaćanje, bočna traka za korpu ili bočna traka za primljenu narudžbu). U suprotnom, stranica ostaje kao jedna kolona sa stilovima &quot;Podijeljeno&quot;.','Split column background' => 'Pozadina podijeljene kolone','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'Odaberite boju pozadine za sekundarnu kolonu Podijeljeni dizajn. Ostavite prazno da biste koristili boju pozadine sažetka narudžbe.','Page templates' => 'Predlošci stranica','Checkout template' => 'Predložak za plaćanje','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'Preporučuje se za manje ometanja prilikom plaćanja. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Pročitajte istraživanje o napuštanju korpe</a> .','Sticky progress bar' => 'Ljepljiva traka napretka','Progress bar style' => 'Stil trake napretka','Order totals' => 'Ukupni iznosi narudžbi','Background color' => 'Boja pozadine','Action link' => 'Link akcije','Mobile order summary' => 'Sažetak mobilne narudžbe','Mobile initial state' => 'Početno stanje mobilnog uređaja','Enable editing cart items at checkout' => 'Omogući uređivanje artikala u korpi prilikom plaćanja','Allow customers to change product quantities or remove items directly at the checkout page.' => 'Omogućite kupcima da mijenjaju količine proizvoda ili uklanjaju artikle direktno na stranici za plaćanje.','Cart item errors' => 'Greške u korpi','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Primjenjivo samo kada je kod kupona prikazan kao zaseban odjeljak na stranicama za plaćanje ili košaricu i ako je korištenje kodova kupona omogućeno u postavkama WooCommerce-a.','Coupon codes position' => 'Pozicija kuponskih kodova','Apply coupon button' => 'Dugme za primjenu kupona','Select style of the "apply coupon" button.' => 'Odaberite stil dugmeta &quot;primijeni kupon&quot;.','Address line 2' => 'Adresa, red 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'Ova postavka se dijeli između odjeljaka Plaćanje i Lokalno preuzimanje. U odjeljku Lokalno preuzimanje, ona također određuje da li se birač Dostava/Preuzimanje prikazuje unutar odjeljka za način dostave (prije adrese) ili kao zaseban odjeljak (poslije).','Customer accounts' => 'Računi kupaca','Guest checkout' => 'Odjava gosta','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'Opcije za plaćanje gosta, prijavu i kreiranje računa sa stranice postavki WooCommerce računa. Ovdje se upravljaju radi vaše udobnosti, tako da možete koristiti različite vrijednosti po profilu postavki.','Allow customers to checkout without an account' => 'Omogućite kupcima plaćanje bez kreiranja računa','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => '<strong>Preporučuje se</strong> kako se od kupaca ne bi tražilo da kreiraju račun ili se prijave tokom plaćanja, što može smanjiti stopu konverzije.','When disabled, customers must log in or create an account to complete the purchase.' => 'Kada je onemogućeno, kupci se moraju prijaviti ili kreirati račun kako bi dovršili kupovinu.','Login at checkout' => 'Prijava prilikom plaćanja','Enable log-in during checkout' => 'Omogući prijavu tokom plaćanja','Show a link for returning customers to log in from the checkout page.' => 'Prikažite link za prijavu stalnim kupcima sa stranice za plaćanje.','Account creation' => 'Kreiranje računa','Allow customers to create an account during checkout' => 'Omogućite kupcima da kreiraju račun tokom plaćanja','Customers can create an account before placing their order.' => 'Kupci mogu kreirati račun prije nego što naruče.','Allow customers to create an account from the My account page' => 'Omogućite korisnicima da kreiraju račun sa stranice Moj račun','Customers can register a new account from the My account page.' => 'Korisnici mogu registrovati novi račun sa stranice Moj račun.','Username' => 'Korisničko ime','Generate from customer\'s name' => 'Generiraj iz imena kupca','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => '<strong>Preporučuje se</strong> kako se od kupaca ne bi tražilo da odaberu korisničko ime prilikom plaćanja, što može smanjiti stopu konverzije.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'Korisničko ime se generira iz imena kupca ili iz adrese e-pošte kada se ime ne može koristiti.','Password' => 'Lozinka','Send password setup link' => 'Pošalji link za postavljanje lozinke','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => '<strong>Preporučuje se</strong> kako se od kupaca ne bi tražilo da postave lozinku prilikom plaćanja, što može smanjiti stopu konverzije.','Customers receive an email to create their password securely.' => 'Korisnici će dobiti e-poruku za sigurno kreiranje lozinke.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'Omogućite registrovanim kupcima da završe narudžbu bez prijave i povežite narudžbu sa svojim postojećim računom kada se kontakt podaci podudaraju.','Existing account message' => 'Poruka o postojećem računu','Let customers create an account after placing their order, from the thank you page.' => 'Omogućite kupcima da kreiraju račun nakon što naruče, sa stranice zahvale.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'Opcije u ovom odjeljku su dostupne kada su omogućeni gostujući račun i uparivanje računa. Omogućite obje funkcije iznad da biste konfigurirali odgođeno kreiranje računa.','Enable delayed account creation' => 'Omogući odloženo kreiranje računa','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'Omogući odloženo kreiranje računa kada su omogućeni i plaćanje gosta i uparivanje računa.','Section position' => 'Položaj sekcije','Before customer details section' => 'Prije odjeljka s detaljima o kupcu','After customer details section' => 'Nakon odjeljka s detaljima o kupcu','Account creation benefits' => 'Prednosti kreiranja računa','Leaving the field empty will display the default text.' => 'Ako polje ostavite prazno, prikazat će se zadani tekst.','Inline buttons' => 'Ugrađena dugmad','Required fields' => 'Obavezna polja','Enable gift message fields at checkout' => 'Omogući polja za poruku poklona prilikom plaćanja','Expanded gift message' => 'Proširena poruka za poklon','Display gift message field always expanded' => 'Polje za poruku poklona uvijek je prošireno','Gift message in order details' => 'Poklon poruka u detaljima narudžbe','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'Trenutno nema dostupnih integracija u ovom odjeljku. Opcije vezane za svaki dodatak i temu pojavit će se ovdje samo kada se taj dodatak ili tema aktiviraju.','Phone fields' => 'Polja za telefon','Field visibility' => 'Vidljivost polja','Field position' => 'Pozicija na terenu','Phone country code & validation' => 'Pozivni broj zemlje i validacija','Country' => 'Zemlja','Enable country on phone fields' => 'Omogući državu u poljima za telefon','Filter countries for shipping or billing' => 'Filtrirajte zemlje za dostavu ili naplatu','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'Ograničite birač zemlje u svakom polju za telefon na zemlje koje su dozvoljene za dostavu ili naplatu u vašoj trgovini.','Validation' => 'Validacija','Enable simple validation based on country rules' => 'Omogućite jednostavnu validaciju na osnovu pravila zemlje','Checks that the phone number is valid for the selected country, including country code and length.' => 'Provjerava da li je broj telefona važeći za odabranu zemlju, uključujući pozivni broj zemlje i dužinu.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'Stroža provjera je da li je broj važeći mobilni, fiksni ili neki drugi prihvaćeni tip za odabranu zemlju. Moguće je da će neki važeći brojevi biti odbijeni.','Validation types' => 'Vrste validacije','Placeholders' => 'Rezervirana mjesta','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'Trenutno nema licencnih ključeva za upravljanje. Licencni ključevi će se pojaviti ovdje kada je aktivan licencirani dodatak ili dodatak za Fluid Checkout.','Default delivery type' => 'Zadana vrsta isporuke','Choose which delivery type will be selected by default.' => 'Odaberite koja vrsta isporuke će biti odabrana prema zadanim postavkama.','Shipping zone fields' => 'Polja zone dostave','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'Odaberite koja će polja biti prikazana za polja filtera za lokalnu zonu dostave preuzimanja. Ostavite prazno da biste prikazali sve dostupne opcije.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'Ova polja će biti prikazana kao filter za lokalne načine dostave preuzimanja. Neka polja se mogu i dalje prikazivati prilikom plaćanja čak i ako nisu ovdje odabrana, ako kompatibilni dodaci zahtijevaju da ispravno rade.','Order shipping address' => 'Adresa za dostavu narudžbe','Order pay page optimization' => 'Optimizacija stranice za plaćanje narudžbe','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'Dajte neplaćenim narudžbama isti jasan, na konverziju usmjeren izgled kao i prilikom plaćanja.','Optimize the layout of the order pay page for orders pending payment.' => 'Optimizirajte izgled stranice za plaćanje narudžbe za narudžbe koje čekaju na plaćanje.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'Uskladite iskustvo plaćanja narudžbe s vašim plaćanjem za dosljedan proces kupovine.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'Dodajte simbole povjerenja i značke tamo gdje kupcima treba uvjeravanje prije plaćanja.','Thank you page optimization' => 'Hvala na optimizaciji stranice','Make the thank you page and order details clearer for customers after they buy.' => 'Učinite stranicu zahvalnosti i detalje narudžbe jasnijima za kupce nakon što obave kupovinu.','Optimize the thank you page and account order details with a clearer layout.' => 'Optimizirajte stranicu zahvale i detalje narudžbe računa jasnijim izgledom.','Show order status progress, actions, downloads, and notes where they make sense.' => 'Prikažite napredak statusa narudžbe, radnje, preuzimanja i bilješke gdje je to logično.','Customize order details sections on email notifications.' => 'Prilagodite odjeljke s detaljima narudžbe u obavijestima putem e-pošte.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'Dodajte simbole povjerenja i značke tamo gdje kupcima treba uvjeravanje nakon kupovine.','Email notifications' => 'Obavještenja putem e-pošte','Enable thank you page and order details optimizations to see more options' => 'Omogućite optimizaciju stranice zahvale i detalja narudžbe da biste vidjeli više opcija','Use wide layout on thank you page' => 'Koristite široki raspored na stranici zahvalnosti','These options affect the thank you page, view order details on account pages and on email notifications.' => 'Ove opcije utiču na stranicu zahvale, pregled detalja narudžbe na stranicama računa i na obavještenja putem e-pošte.','Save settings' => 'Sačuvaj postavke','Docs' => 'Dokumenti','Cart' => 'Košarica','Thank you' => 'Hvala ti','Address autocomplete' => 'Automatsko dovršavanje adrese','Trust badges' => 'Značke povjerenja','You do not have permission to save these settings.' => 'Nemate dozvolu za spremanje ovih postavki.','Invalid save request.' => 'Nevažeći zahtjev za spremanje.','Your settings have been saved.' => 'Vaše postavke su sačuvane.','Saving...' => 'Spremanje...','Settings could not be saved. Please try again.' => 'Postavke nisu sačuvane. Pokušajte ponovo.','Dismiss notice' => 'Odbaci obavještenje','Open settings menu' => 'Otvori meni postavki','Close settings menu' => 'Zatvori meni postavki','Preview' => 'Pregled','Expand preview' => 'Proširi pregled','Collapse preview' => 'Sažmi pregled','Show header and footer' => 'Prikaži zaglavlje i podnožje','Hide header and footer' => 'Sakrij zaglavlje i podnožje','Page preview' => 'Pregled stranice','Preview viewport' => 'Pregled prikaza','Tablet' => 'Tablet','Desktop' => 'Desktop','Preview width' => 'Širina pregleda','Decrease width' => 'Smanji širinu','Preview width in pixels' => 'Širina pregleda u pikselima','Increase width' => 'Povećaj širinu','Preview as' => 'Pregledaj kao','Guest' => 'Gost','Logged in' => 'Prijavljen','Preview page' => 'Pregled stranice','Expand preview for a closer look' => 'Proširite pregled za detaljniji pogled','Available with %s.' => 'Dostupno uz %s.','Turn them on' => 'Uključite ih','Optimizations for this page are turned off. %s to preview the page.' => 'Optimizacije za ovu stranicu su isključene. %s za pregled stranice.','%s preview' => '%s pregled','Isolated session · nothing is saved' => 'Izolirana sesija · ništa nije sačuvano','Usage tracking' => 'Praćenje korištenja','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'Šaljite neosjetljive izvještaje o okruženju web-mjesta kako biste pomogli Fluid Checkoutu da poboljša kompatibilnost. Izvještaji se ne šalju dok se ne omoguće u opcijama ispod.','Send usage tracking reports to Fluid Checkout' => 'Pošaljite izvještaje o praćenju korištenja Fluid Checkout-u','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'Ovi izvještaji nam pomažu da poboljšamo kompatibilnost i podršku za vašu web stranicu i šalju se sedmično kada su omogućeni.','No customer, admin user, or any other sensitive data is included in the reports.' => 'Izvještaji ne sadrže podatke o kupcima, administratorima ili bilo koje druge osjetljive podatke.','Basic environment info' => 'Osnovne informacije o okruženju','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'Podaci o WordPressu, PHP-u, WooCommerceu, temama i popisima dodataka. Uvijek uključeni kada je omogućeno izvještavanje. Pomažu nam da razumijemo okruženje u kojem vaša web stranica radi.','Plugin settings' => 'Postavke dodatka','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'Šalje postavke dodatka Fluid Checkout kako bi nam pomogao sa zahtjevima za podršku i pomogao nam da razumijemo kako koristite naše dodatke.','Coming soon' => 'Uskoro','Sales metrics' => 'Metrike prodaje','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'Mjesečni broj narudžbi i ukupna prodaja za godinu dana prije instaliranja Fluid Checkout-a do danas. Pomaže nam da shvatimo da li zarađujete više novca s instaliranim našim dodacima. Nikada se ne šalju nikakvi podaci o kupcima ili korisnicima.','Utilities' => 'Komunalne usluge','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => 'Koristite <code>TomSelect</code> komponente padajućeg menija umjesto <code>select2</code>','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect je jednostavnija komponenta za padajući izbor koja je manje sklona greškama od Select2, a istovremeno nudi istu funkcionalnost.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'Postavlja veličinu fonta unutar polja obrasca na 16px na stranicama optimiziranim ovim dodatkom kako bi se izbjeglo automatsko zumiranje prilikom interakcije s poljima obrasca na malim uređajima.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'Safari i drugi preglednici mogu automatski zumirati na mobilnim uređajima kako bi tekst bio lakše čitljiv kada je veličina fonta manja od 16px.','Enable script processing tracking on the browser console.' => 'Omogućite praćenje obrade skripti na konzoli preglednika.','Unminified assets' => 'Neminificirana sredstva','Google Maps scripts' => 'Skripte za Google mape','Do not remove duplicate Google Maps scripts' => 'Ne uklanjajte duplikate skripti za Google mape','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'Kada je omogućeno, duplikati skripti za Google mape NEĆE biti uklonjeni, što može uzrokovati greške i probleme s performansama. Ovu opciju koristite samo prilikom rješavanja problema.','Widget areas' => 'Područja vidžeta','Last step on mobile' => 'Posljednji korak na mobilnom uređaju','Display widgets only at last step on mobile' => 'Prikaži widgete samo u posljednjem koraku na mobilnom uređaju','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'Prikaži widgete za značku povjerenja prilikom plaćanja samo prilikom pregleda posljednjeg koraka plaćanja na mobilnim uređajima','Standard' => 'Standardno','VAT number field' => 'Polje za PDV broj','Add a VAT number field to the billing form.' => 'Dodajte polje za PDV broj u obrazac za naplatu.','Field label' => 'Oznaka polja','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'Postavite oznaku polja za PDV broj (npr. PDV broj). Na višejezičnim web stranicama je bolje ostaviti ovo polje praznim i prevesti originalni niz.','VAT Number' => 'PDV broj','EU-VAT' => 'PDV u EU','Enable the VAT number field to see more options' => 'Omogućite polje PDV broj da biste vidjeli više opcija','VAT validation' => 'Validacija PDV-a','Validate VAT number field for EU-VAT during checkout' => 'Potvrdite polje PDV broja za EU-PDV prilikom plaćanja','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'Provjerava da li je uneseni PDV broj važeći PDV broj registrovan u evropskoj VIES bazi podataka (Sistem za razmjenu informacija o PDV-u).','Shop VAT number' => 'PDV broj trgovine','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'PDV broj trgovine koji se koristi za zahtjev za validaciju PDV-a u EU i koji se štampa na fakturama.<br> <strong>Preporučujemo da dodate PDV broj svoje trgovine</strong> jer u suprotnom rezultati VIES konsultacije možda neće biti važeći u računovodstvene svrhe.<br> Odnosno: <code>ATU99999999</code> ili <code>EE999999999</code> .','Reverse charge' => 'Obrnuta naplata','Apply reverse charge mechanism' => 'Primijenite mehanizam obrnutog oporezivanja','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'Postavite poresku stopu na nulu i prikažite &quot;Obrnuto naplaćivanje&quot; na fakturama kada je PDV broj kupca važeći. Možda će biti potreban drugačiji tekst &quot;Obrnuto naplaćivanje&quot; ovisno o zemlji trgovine.','Same country' => 'Ista zemlja','Apply reverse charge mechanism for transactions in the shop country:' => 'Primijenite mehanizam obrnutog oporezivanja za transakcije u zemlji trgovine:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'Omogućava primjenu mehanizma obrnutog oporezivanja za transakcije između kompanija u istoj zemlji kao i prodavnica.','Reverse charge exceptions' => 'Izuzeci od obrnutog naplatnog postupka','Select additional countries to skip applying the reverse charge mechanism.' => 'Odaberite dodatne zemlje za koje želite preskočiti primjenu mehanizma obrnutog oporezivanja.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'Porezi će se naplaćivati na narudžbe iz ovih zemalja čak i kada je naveden važeći PDV broj.','Reverse charge label on invoices' => 'Oznaka obrnutog naplata na fakturama','Set the label of "reverse charge" on the checkout page and order details.' => 'Postavite oznaku &quot;obrnuta naplata&quot; na stranici za plaćanje i u detaljima narudžbe.','Reverse charge text on invoices' => 'Tekst obrnutog plaćanja na fakturama','Set the label of "reverse charge" text on invoices.' => 'Postavite oznaku teksta &quot;obrnuto naplaćivanje&quot; na fakture.','Tax to be paid on reverse charge basis' => 'Porez koji se plaća po principu obrnutog oporezivanja','Company name' => 'Naziv kompanije','Autocomplete company name from VAT number' => 'Automatsko dopunjavanje naziva kompanije iz PDV broja','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'Unesite naziv kompanije za naplatu na osnovu važećeg PDV broja koji je dostavio kupac.','Company name editing' => 'Uređivanje naziva kompanije','Allow editing of auto-filled company name' => 'Dozvoli uređivanje automatski popunjenog naziva kompanije','When enabled, customers can change the company name associated with the provided VAT number.' => 'Kada je omogućeno, korisnici mogu promijeniti naziv kompanije povezan s navedenim PDV brojem.','EU-VAT for digital goods' => 'PDV u EU za digitalnu robu','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => 'Od 1. januara 2015. godine, izvršene su izmjene propisa EU o PDV-u koje se odnose na digitalnu robu, a koje se odnose isključivo na B2C transakcije. PDV na digitalnu robu mora se obračunavati na osnovu lokacije kupca, a za to je potrebno prikupiti dokaze (IP adresa i adresa za naplatu).','Tax classes for digital goods' => 'Poreske klase za digitalnu robu','Select some tax classes' => 'Odaberite neke poreske klase','Location evidence' => 'Dokazi o lokaciji','Collect customer\'s location evidence' => 'Prikupite dokaze o lokaciji kupca','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'Sprema IP adresu i provjerava je u odnosu na adresu za naplatu kupca. Kupci moraju potvrditi svoju adresu za naplatu označavanjem kućice na stranici za plaćanje ako se država s njihove adrese za naplatu i IP adrese ne podudaraju.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'Ova opcija se upravlja u Fluid Checkout-u. <a href="%s">Promijenite je u postavkama korisničkih računa</a> .','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'Ova opcija se upravlja u Fluid Checkout-u. Promijenite je u Fluid Checkout-u &gt; Računi kupaca.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'Ova opcija se upravlja u Fluid Checkout-u. Odredište dostave je uvijek postavljeno na &quot;Zadana adresa za dostavu kupca&quot; kada je Fluid Checkout aktiviran. Kupci i dalje mogu navesti različite adrese za dostavu i naplatu tokom plaćanja.<br><br> U <a href="%s">postavkama Fluid Checkout-a</a> dostupna je opcija za postavljanje zadane adrese za naplatu koja je ista kao i adresa za dostavu.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'Ova opcija se upravlja u Fluid Checkout-u. Odredište dostave je uvijek postavljeno na &quot;Zadana adresa za dostavu kupca&quot; kada je Fluid Checkout aktiviran. Kupci i dalje mogu navesti različite adrese za dostavu i naplatu tokom plaćanja.<br><br> Opcija za postavljanje zadane adrese za naplatu da bude ista kao i adresa za dostavu dostupna je u WooCommerce &gt; Postavke &gt; Fluid Checkout.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'Ove postavke su premještene u WP Admin &gt; Fluid Checkout &gt; Postavke.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'Ova kartica Postavke WooCommerce-a je zastarjela i bit će uklonjena u Fluid Checkout 6.0.','Go to settings page' => 'Idi na stranicu postavki','Hide this tab permanently' => 'Trajno sakrij ovu karticu','Site report preview' => 'Pregled izvještaja o web-lokaciji','This is the data that would be included in the next site environment report based on your current settings.' => 'Ovo su podaci koji bi bili uključeni u sljedeći izvještaj o okruženju lokacije na osnovu vaših trenutnih postavki.','Loading report preview...' => 'Učitavanje pregleda izvještaja...','Could not load the site report preview. Try again.' => 'Nije moguće učitati pregled izvještaja o web-lokaciji. Pokušajte ponovo.','Could not send the site report. Try again.' => 'Nije moguće poslati izvještaj o lokaciji. Pokušajte ponovo.','Site report sent successfully.' => 'Izvještaj sa stranice uspješno poslan.','Enable and send now' => 'Omogući i pošalji odmah','Close' => 'Zatvori','A site report request is already in progress. Try again in a moment.' => 'Zahtjev za izvještaj o lokaciji je već u toku. Pokušajte ponovo za trenutak.','Site environment reporting is disabled.' => 'Izvještavanje o okruženju lokacije je onemogućeno.','No site report data is available to send.' => 'Nema dostupnih podataka izvještaja o lokaciji za slanje.','This site domain cannot send environment reports (local or development domains are excluded).' => 'Ova domena web-lokacije ne može slati izvještaje o okruženju (lokalne ili razvojne domene su isključene).','A site report was sent recently. Try again later.' => 'Izvještaj o lokaciji je nedavno poslan. Pokušajte ponovo kasnije.','The site report could not be sent. Try again later.' => 'Izvještaj o lokaciji nije mogao biti poslan. Pokušajte ponovo kasnije.','Site environment reporting is not available.' => 'Izvještavanje o okruženju lokacije nije dostupno.','No site report data is available for the selected settings.' => 'Za odabrane postavke nisu dostupni podaci izvještaja o lokaciji.','You are not allowed to manage site reports.' => 'Nije vam dozvoljeno upravljanje izvještajima o web-lokaciji.','PRO feature' => 'PRO funkcija','Other plugins' => 'Ostali dodaci','Get only this add-on &mdash; %s' => 'Preuzmite samo ovaj dodatak — %s','Install add-on' => 'Instaliraj dodatak','Upgrade to PRO &mdash; %s' => 'Nadogradite na PRO verziju — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => '<a target="_blank" href="%1$s">Nabavite %2$s</a> da biste otključali ove opcije.','Add-on' => 'Dodatak','View documentation' => 'Pogledajte dokumentaciju','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'Zahtjevi zahtijevaju prijavljenog WordPress korisnika. Izostavite user_id da biste koristili podatke trenutnog korisnika ili proslijedite user_id da biste ciljali drugi račun kada pozivatelj može uređivati tog korisnika (mogućnost edit_user). Neautentificirani zahtjevi vraćaju fc_api_forbidden. Nevažeći user_id vraća fc_api_user_not_found.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200 sa { &quot;data&quot;: { ... } } kada rukovalac vrati korisni teret.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200 sa { &quot;success&quot;: true } kada nema korisnog tereta (na primjer DELETE).','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'Neuspjesi vraćaju WordPress REST grešku JSON iz WP_Error (code, message, data.status). Kodovi za žičanu vezu koriste prefiks fc_api_*.','Forbidden access.' => 'Zabranjen pristup.','Target user was not found.' => 'Ciljani korisnik nije pronađen.','This feature is not available.' => 'Ova funkcija nije dostupna.','A required address field is missing.' => 'Nedostaje obavezno polje za adresu.','Postcode or ZIP is invalid.' => 'Poštanski broj je nevažeći.','Phone number is invalid.' => 'Broj telefona je nevažeći.','State or county is invalid.' => 'Država ili okrug je nevažeći.','Country is invalid or has no address fields.' => 'Država je nevažeća ili nema polja za adresu.','The request could not be processed.' => 'Zahtjev nije mogao biti obrađen.','Back to previous step' => 'Nazad na prethodni korak','Skip to settings' => 'Preskoči na postavke','Start over and return to the first guided setup step' => 'Počnite ispočetka i vratite se na prvi korak vođenog podešavanja','Start over' => 'Počni ispočetka','Please complete all sub-steps before continuing.' => 'Molimo Vas da završite sve podkorake prije nego što nastavite.','Expand' => 'Proširi','Collapse' => 'Sažmi','Skip' => 'Preskoči','Mark as complete' => 'Označi kao završeno','Mark as incomplete' => 'Označi kao nepotpuno','View full-size image: %s' => 'Pogledajte sliku u punoj veličini: %s','Full-size setup guide image' => 'Slika vodiča za podešavanje u punoj veličini','Close image' => 'Zatvori sliku','Fluid Checkout Guided Setup' => 'Vođeno podešavanje za Fluid Checkout','Welcome' => 'Dobrodošli','Explore your checkout' => 'Istražite svoju blagajnu','All set' => 'Sve spremno','You do not have permission to access this page.' => 'Nemate dozvolu za pristup ovoj stranici.','Go to step %1$d: %2$s' => 'Idi na korak %1$d: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'Ovaj vodič za podešavanje vam pomaže da se upoznate sa Fluid Checkout-om. Koraci u nastavku su za sada samo okvirni.','Continue to the next step when you are ready.' => 'Nastavite na sljedeći korak kada budete spremni.','Open your store checkout to see Fluid Checkout in action.' => 'Otvorite blagajnu u trgovini da biste vidjeli Fluid Checkout u akciji.','View checkout page' => 'Pogledajte stranicu za plaćanje','You can return to Fluid Checkout settings to continue configuring your store.' => 'Možete se vratiti na postavke Fluid Checkout-a da biste nastavili s konfigurisanjem svoje trgovine.','Review checkout and cart settings' => 'Pregledajte postavke plaćanja i korpe','Explore add-ons from the dashboard' => 'Istražite dodatke s kontrolne ploče','Finish & go to settings' => 'Završi i idi na postavke','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Ažurirajte opciju vidljivosti polja telefona za naplatu sa zastarjele vrijednosti kako bi odgovarala WooCommerce konvencijama.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Ažurirajte opciju vidljivosti polja za broj telefona za dostavu sa zastarjele vrijednosti kako bi odgovarala WooCommerce konvencijama.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'Kopirajte postavku boje pozadine sažetka narudžbe u novu opciju boje pozadine sekundarne kolone Podijeljeni dizajn.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'Poboljšana funkcija odabira polja je uvijek onemogućena kada se koristi Biteship dodatak.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Pozicija narudžbe je uvijek postavljena na &quot;Ispod sažetka narudžbe&quot; kada se koristi njemačko tržište. Taj dodatak zahtijeva da se dugme za narudžbu i legalni potvrdni okviri prikazuju ispod sažetka narudžbe.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Pozicija narudžbe je uvijek postavljena na &quot;Ispod sažetka narudžbe&quot; kada se koristi Germanized za WooCommerce. Taj dodatak zahtijeva da se dugme za narudžbu i legalni potvrdni okviri prikazuju ispod sažetka narudžbe.','Edit pickup locations' => 'Uredi lokacije preuzimanja','Use local pickup label from WooCommerce settings' => 'Koristite lokalnu etiketu za preuzimanje iz postavki WooCommerce-a','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'Kada je omogućeno, oznaka opcije preuzimanja prilikom plaćanja odgovara naslovu iz postavki lokacije preuzimanja u WooCommerce-u. Kada je onemogućeno, oznaka koristi prevodivi tekst &quot;Lokalno preuzimanje&quot; iz Fluid Checkout-a.','Button label for applying coupon codesApply' => 'Prijavite se','Checkout step titleContact' => 'Kontakt','Checkout step titleShipping' => 'Dostava','Checkout step titleBilling' => 'Naplata','Checkout step titlePayment' => 'Plaćanje','Checkout substep change link labelChange' => 'Promjena','Checkout substep save link labelSave changes' => 'Sačuvaj promjene','Substep review textNone.' => 'Nema.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'Nijedna slika nije odabrana.','Settings sectionCart' => 'Cart','Settings sectionOrder pay' => 'Naručite plaćanje','Settings sectionThank you' => 'Hvala','Settings section titleIntegrations' => 'Integracije','Settings section titleLicense keys' => 'Licencni ključevi','Captcha positionBefore place order section' => 'Prije naručivanja odjeljka','Captcha positionBefore place order button' => 'Dugme pre naručivanja','No shipping method chosen label for the order summary--' => '--','Close button aria-labelClose' => 'Zatvori','Log in link label at checkout contact stepLog in' => 'Prijavite se','Log in separator label at for when guest checkout is disabledOr continue below' => 'Ili nastavite ispod','Log in separator label at for when guest checkout is disabledOr continue as a guest' => 'Ili nastavite kao gost','Clear image selection on admin pages.Remove image' => 'Ukloni sliku','shipping packagesShipping %d' => 'Dostava %d','shipping packagesShipping' => 'Dostava','Used as fallback for "Proceed to next step" button labelnext step' => 'sljedeći korak','Substep review checkbox valueYes' => 'Da','Substep review checkbox line%1$s: %2$s' => '%1$s: %2$s','Dummy customer first name in the admin previewJohn' => 'Ivan','Dummy customer last name in the admin previewDoe' => 'Srna','Dummy customer company in the admin previewExample Company' => 'Primjer kompanije','Dummy customer street address in the admin preview123 Main Street' => 'Glavna ulica 123','Dummy customer city in the admin previewAnytown' => 'Bilo koji grad','Dummy order notes in the admin previewPlease leave the package at the front door.' => 'Molimo vas da paket ostavite na ulaznim vratima.','Dummy product name in the admin previewBeanie' => 'Kapa','Dummy product name in the admin previewCap' => 'Kapa','Dummy product name in the admin previewT-Shirt' => 'Majica kratkih rukava','Dummy order update in the admin previewWe received your order and will send you an update when it ships.' => 'Primili smo vašu narudžbu i poslat ćemo vam ažuriranje kada bude poslana.','Dummy download in the admin previewUser guide' => 'Vodič za korisnike','Google Places API versionsPlaces API (New)' => 'API za mjesta (novo)','Google Places API versionsPlaces API (Legacy)' => 'API za mjesta (zastarjelo)','Brasil API versionsVersion 1' => 'Verzija 1','Brasil API versionsVersion 2' => 'Verzija 2','Delayed account creation benefits placeholder text✔ Checkout faster next time
✔ Manage your payment preferences
✔ View order status and history' => '✔ Brža naplata sljedeći put ✔ Upravljajte postavkama plaćanja ✔ Pregledajte status i historiju narudžbe','VAT number field visibilityHidden' => 'Skriveno','VAT number field visibilityOptional' => 'Opcionalno','VAT number field visibilityRequired' => 'Obavezno','Delivery typeShipping to address' => 'Dostava na adresu','Delivery typeLocal pickup' => 'Lokalno preuzimanje',] ];